    // line 29
    vela_builder_add(v_out, VELA_STR("Run/test flags precede FILE: `--allow unsafe`, `--allow fs:PATH`, `--deny EFFECT`. Unsafe requires allow; standalone builds are unrestricted. Deny wins; fs roots narrow access. Unsupported policies fail closed. macOS deny-net forbids unsafe and subprocesses; use Linux for restricted C.\012\012", 288));
    // line 30
    vela_builder_add(v_out, VELA_STR("## Syntax and values\012", 21));
